paid = (
    context.sql(
        "SELECT region, SUM(amount_minor) AS total, COUNT(*) AS orders "
        "FROM orders WHERE paid GROUP BY region ORDER BY region"
    )
    .to_arrow_table()
    .to_pylist()
)
expected = [
    {
        "region": "east",
        "total": sum(r["amount_minor"] for r in records if r["paid"]),
        "orders": sum(r["paid"] for r in records),
    }
]
assert paid == expected == [{"region": "east", "total": 1100, "orders": 2}]

schema = pa.schema(
    [("id", pa.int64()), ("amount_minor", pa.int64())], metadata={b"currency": b"fixture-USD"}
)
batches = [
    pa.record_batch([[1, 2], [1299, 2500]], schema=schema),
    pa.record_batch([[3], [700]], schema=schema),
]

bad = pa.record_batch([[4], ["900"]], names=["id", "amount_minor"])
with ipc.new_stream(pa.BufferOutputStream(), schema) as writer:
    try:
        writer.write_batch(bad)
    except (pa.ArrowInvalid, ValueError):
        print("Mismatched batch schema rejected")
    else:
        raise AssertionError("Expected a schema mismatch")

try:
    with stale.update_schema() as update:
        update.add_column("stale_field", LongType())
except CommitFailedException as error:
    print("Actual stale commit rejected:", type(error).__name__)
else:
    raise AssertionError("Stale schema commit accepted")
